const items = $input.all();

function findKey(obj, candidates) {
  const keys = Object.keys(obj);
  for (const c of candidates) {
    const match = keys.find(k => k.toLowerCase().includes(c.toLowerCase()));
    if (match !== undefined && obj[match] !== null && obj[match] !== undefined) return String(obj[match]).trim();
  }
  return null;
}

function parsePhone(raw) {
  if (!raw) return null;
  const str = String(raw).replace(/\s/g, '');
  const match = str.match(/^(97\d)\|?(.+)$/);
  if (match) {
    const code   = match[1];
    const number = match[2].replace(/\D/g, '');
    if (number.length < 6) return null;
    return { code, number, full: code + number };
  }
  const digits = str.replace(/\D/g, '');
  if (digits.length < 6) return null;
  return { code: null, number: digits, full: digits };
}

function bestPhone(row) {
  const candidates = [
    findKey(row, ['Mobile 1', 'mobile1', 'mobile_1']),
    findKey(row, ['Phone 1',  'phone1',  'phone_1']),
    findKey(row, ['Mobile 2', 'mobile2', 'mobile_2']),
    findKey(row, ['Phone 2',  'phone2',  'phone_2']),
    findKey(row, ['Secondary Mobile', 'sec_mobile', 'secondary']),
  ];
  const seen = new Set();
  for (const raw of candidates) {
    const parsed = parsePhone(raw);
    if (!parsed) continue;
    if (seen.has(parsed.number)) continue;
    seen.add(parsed.number);
    return parsed;
  }
  return null;
}

const results = [];
for (const item of items) {
  const row = item.json;
  const vals = Object.values(row).filter(v => v !== null && v !== undefined && String(v).trim() !== '');
  if (vals.length === 0) continue;
  const phone = bestPhone(row);
  results.push({
    json: {
      owner_name:          findKey(row, ['Owner Name', 'owner']),
      phone_country_code:  phone ? phone.code : null,
      phone_wa:            phone ? phone.full : null,
      sms_number:          phone ? phone.full : null,
      email:               findKey(row, ['Email', 'email']) || '',
      language:            'en',
      property_ref:        findKey(row, ['Property Number', 'property_ref', 'ref']),
      area:                findKey(row, ['Master Location', 'location', 'area']),
      project:             findKey(row, ['Master Project', 'project']),
      building:            findKey(row, ['Building 1', 'building']),
      unit_number:         findKey(row, ['UnitNumber', 'unit_number', 'unit']),
      property_type:       findKey(row, ['PropertyType', 'property_type', 'type']),
      beds:                findKey(row, ['Beds', 'bedrooms', 'bed']),
      transaction_amount:  findKey(row, ['Transaction Amount', 'transaction', 'amount', 'price']),
      actual_size:         findKey(row, ['Actual Size', 'actual_size', 'size']),
      completion_status:   findKey(row, ['Completion Status', 'status']),
      telegram_id:         findKey(row, ['telegram_id', 'Telegram ID', 'telegram']),
    }
  });
}

return results;
